SELECT md.chembl_id, md.pref_name, cs.canonical_smiles, 'EFO:' || di.efo_id AS indication_curie, di.mesh_heading AS indication_label, di.max_phase_for_ind FROM molecule_dictionary md JOIN drug_indication di ON md.molregno = di.molregno JOIN compound_structures cs ON md.molregno = cs.molregno WHERE md.max_phase = 4 AND di.mesh_heading = 'chronic kidney disease' ORDER BY md.chembl_id ASC, md.pref_name ASC, cs.canonical_smiles ASC, indication_curie ASC, indication_label ASC, di.max_phase_for_ind ASC
